import{_ as t,o as a,c as d,a3 as s}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"缓存与异步","description":"","frontmatter":{},"headers":[],"relativePath":"backend/caching.md","filePath":"backend/caching.md","lastUpdated":1786258579000}'),o={name:"backend/caching.md"};function c(n,e,i,r,l,h){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="缓存与异步" tabindex="-1">缓存与异步 <a class="header-anchor" href="#缓存与异步" aria-label="Permalink to &quot;缓存与异步&quot;">​</a></h1><p>BasicApp 的热点读路径走 Redis 分布式缓存，写路径<strong>精准失效</strong>；耗时动作（发邮件短信、导出）不占请求线程，走队列 + 后台消费。这两条机制的时序稍有偏差就会出现「改完不生效」「读到脏数据」「任务丢了」，本页把它们说透。</p><h2 id="缓存" tabindex="-1">缓存 <a class="header-anchor" href="#缓存" aria-label="Permalink to &quot;缓存&quot;">​</a></h2><h3 id="三层结构" tabindex="-1">三层结构 <a class="header-anchor" href="#三层结构" aria-label="Permalink to &quot;三层结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 缓存条目类（Application/Caching/Saas*CacheItem.cs）</span></span>
<span class="line"><span>     一个热点读定义一个条目类，用 [CacheName] 绑定缓存名并定义缓存值结构</span></span>
<span class="line"><span>② 缓存键常量（SaasCacheNames / SaasCacheKeys）</span></span>
<span class="line"><span>     缓存名一律 const 集中在 SaasCacheNames，业务键/匹配模式由 SaasCacheKeys 拼，禁止内联字符串</span></span>
<span class="line"><span>③ 失效器（ISaasCacheInvalidator / SaasCacheInvalidator）</span></span>
<span class="line"><span>     按域提供精准失效方法，底层 RemoveByPatternAsync(..., considerUow: true)</span></span></code></pre></div><h3 id="缓存条目一览" tabindex="-1">缓存条目一览 <a class="header-anchor" href="#缓存条目一览" aria-label="Permalink to &quot;缓存条目一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>缓存条目</th><th>键前缀</th><th>用途</th></tr></thead><tbody><tr><td><code>SaasAuthorizationSnapshotCacheItem</code></td><td><code>basicapp:saas:auth:snapshot</code></td><td><strong>授权快照</strong>——请求期鉴权热路径，让授权变更免重登即生效</td></tr><tr><td><code>SaasMenuRoutesCacheItem</code></td><td><code>basicapp:saas:navigation:routes</code></td><td>菜单路由（前端动态路由数据源）</td></tr><tr><td><code>SaasConfigValueCacheItem</code></td><td><code>basicapp:saas:config:value</code></td><td>系统参数值</td></tr><tr><td><code>SaasDictItemTreeCacheItem</code></td><td><code>basicapp:saas:configuration:dict-tree</code></td><td>字典项树（下拉高频读）</td></tr><tr><td><code>SaasEditionGateCacheItem</code></td><td><code>basicapp:saas:tenancy:edition-gate</code></td><td>租户版本权限白名单门控</td></tr><tr><td><code>SaasEnabledEditionsCacheItem</code></td><td><code>basicapp:saas:tenancy:editions</code></td><td>启用中的版本套餐</td></tr><tr><td><code>SaasMessageTemplateCacheItem</code></td><td><code>basicapp:saas:message:template</code></td><td>消息模板（发送链路高频读）</td></tr><tr><td><code>SaasDepartmentTreeCacheItem</code></td><td><code>basicapp:saas:organization:dept-tree</code></td><td>部门树</td></tr><tr><td><code>SaasUserSettingCacheItem</code></td><td><code>basicapp:saas:user:setting</code></td><td>用户 UI 偏好</td></tr><tr><td><code>SaasSessionStateCacheItem</code></td><td><code>basicapp:saas:identity:session-state</code></td><td>会话状态（会话闸门读它判 401/423）</td></tr><tr><td><code>SaasPermissionSelectCacheItem</code> / <code>SaasRoleSelectCacheItem</code> / <code>SaasResourceSelectCacheItem</code> / <code>SaasOperationSelectCacheItem</code></td><td><code>basicapp:saas:{域}:select</code></td><td>各类下拉选择项</td></tr><tr><td><code>SaasTelegramConversationStateCacheItem</code></td><td><code>basicapp:saas:bot:telegram-conversation</code></td><td>Telegram 会话态</td></tr></tbody></table><p>缓存名统一在 <code>SaasCacheNames</code> 里定义为 <code>const</code>（条目类用 <code>[CacheName]</code> 引用），业务键与匹配模式拼接在 <code>SaasCacheKeys</code>。<strong>新增缓存必须走这套，不要内联字符串</strong>——否则失效器找不到你的键。</p><h3 id="失效器" tabindex="-1">失效器 <a class="header-anchor" href="#失效器" aria-label="Permalink to &quot;失效器&quot;">​</a></h3><p><code>ISaasCacheInvalidator</code> 按域给出精准失效方法，而不是「一把清空」：</p><table tabindex="0"><thead><tr><th>方法</th><th>影响</th></tr></thead><tbody><tr><td><code>InvalidateAuthorizationAsync(userId?)</code></td><td>授权快照；传 <code>userId</code> 只清该用户，不传清全部</td></tr><tr><td><code>InvalidateNavigationAsync()</code></td><td>菜单路由</td></tr><tr><td><code>InvalidateConfigurationAsync(configKey?)</code></td><td>系统参数</td></tr><tr><td><code>InvalidateDictionaryAsync()</code></td><td>字典项树</td></tr><tr><td><code>InvalidateEditionGateAsync()</code> / <code>InvalidateTenantEditionAsync()</code></td><td>版本门控 / 版本套餐</td></tr><tr><td><code>InvalidateOrganizationAsync()</code></td><td>部门树</td></tr><tr><td><code>InvalidateMessageTemplateAsync()</code></td><td>消息模板</td></tr><tr><td><code>InvalidateUserSettingAsync(userId)</code></td><td>指定用户偏好</td></tr><tr><td><code>InvalidatePermissionDefinitionAsync()</code> / <code>InvalidateRoleDefinitionAsync()</code> / <code>InvalidateResourceDefinitionAsync()</code> / <code>InvalidateOperationDefinitionAsync()</code></td><td>各类定义与下拉</td></tr><tr><td><code>InvalidateSessionStateAsync(userSessionId)</code> / <code>InvalidateAllSessionStatesAsync()</code></td><td>会话状态</td></tr></tbody></table><p>写侧 <code>*AppService</code> 改完数据后调对应方法，例如 <code>ConfigAppService</code> 在增删改后调 <code>InvalidateConfigurationAsync</code>。</p><h3 id="consideruow-true-是关键" tabindex="-1"><code>considerUow: true</code> 是关键 <a class="header-anchor" href="#consideruow-true-是关键" aria-label="Permalink to &quot;\`considerUow: true\` 是关键&quot;">​</a></h3><p>失效底层一律是：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">_configValueCache.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RemoveByPatternAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(pattern, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hideErrors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">considerUow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: ct);</span></span></code></pre></div><p><code>considerUow: true</code> 表示<strong>排队到工作单元提交之后</strong>才真正清缓存。</p><div class="danger custom-block"><p class="custom-block-title">为什么不能立即清</p><p>如果在事务提交前就清了缓存，并发请求会立刻回源查库，读到的是<strong>尚未提交的旧值</strong>，然后把旧值重新写回缓存——事务提交后缓存反而是错的，且不会自愈。这类问题极难复现，务必保持 <code>considerUow: true</code>。</p></div><h3 id="加一个新缓存的清单" tabindex="-1">加一个新缓存的清单 <a class="header-anchor" href="#加一个新缓存的清单" aria-label="Permalink to &quot;加一个新缓存的清单&quot;">​</a></h3><ol><li>在 <code>SaasCacheNames</code> 加缓存名常量；必要时在 <code>SaasCacheKeys</code> 加业务键/匹配模式拼接方法。</li><li>新建 <code>SaasXxxCacheItem</code>，用 <code>[CacheName]</code> 绑定第 1 步的常量并定义值结构。</li><li>读侧 <code>*QueryService</code> 里先查缓存、未命中回源并回填（过期时间在回填时用 <code>DistributedCacheEntryOptions</code> 指定）。</li><li>在 <code>ISaasCacheInvalidator</code> / <code>SaasCacheInvalidator</code> 加一个 <code>InvalidateXxxAsync</code>，底层用 <code>RemoveByPatternAsync(..., considerUow: true)</code>。</li><li><strong>所有会改到该数据的写侧方法都要调它</strong>——漏一个就会出现「某个入口改完不生效」。</li></ol><h2 id="异步-队列承载工作" tabindex="-1">异步：队列承载工作 <a class="header-anchor" href="#异步-队列承载工作" aria-label="Permalink to &quot;异步：队列承载工作&quot;">​</a></h2><p>原则是<strong>队列承载工作 + 拉取消费</strong>，不在请求线程里做耗时动作，也不额外造心跳/调度层。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写侧（请求线程）                      后台常驻服务（XiHanBackgroundServiceBase）</span></span>
<span class="line"><span>   │ 业务行落库（状态 Pending）</span></span>
<span class="line"><span>   │ 事务提交</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>IRedisDelayQueue&lt;T&gt;.EnqueueAsync ─────►  拉取 → 原子领取（置 Sending / Processing）→ 执行 → 置终态</span></span>
<span class="line"><span>   （提交之后才入队）                       │</span></span>
<span class="line"><span>                                            └─ 启动时复位崩溃残留的在途状态 → Pending 并重投</span></span></code></pre></div><p>三条设计要点：</p><ol><li><strong>数据库表是事实源，队列只承载「待办工作」</strong>。状态、重试次数、定时、审计都在表里；队列里只有一个轻量消息（通常就是实体 Id）。</li><li><strong>提交之后才入队</strong>，保证后台拉到消息时业务行已经可见（无环境工作单元时直接入队）。</li><li><strong>原子领取</strong>：发件箱的 <code>TryClaimForSendingAsync</code> 原子地把行由 <code>Pending</code> / 可重试 <code>Failed</code> 置为 <code>Sending</code>（天然去重、按 <code>MaxRetryCount</code> 自限重试）；导出的 <code>ClaimByIdAsync</code> 原子地把行由 <code>Pending</code> 置为 <code>Processing</code>。</li></ol><h3 id="现有的两条异步链路" tabindex="-1">现有的两条异步链路 <a class="header-anchor" href="#现有的两条异步链路" aria-label="Permalink to &quot;现有的两条异步链路&quot;">​</a></h3><table tabindex="0"><thead><tr><th>链路</th><th>入队方</th><th>消费方</th><th>事实源表</th></tr></thead><tbody><tr><td><strong>邮件 / 短信发件箱</strong></td><td><code>DbMessageOutbox.EnqueueAsync(channel, entityId)</code></td><td><code>MessageOutboxHostedService</code></td><td><code>Sys_Email</code> / <code>Sys_Sms</code></td></tr><tr><td><strong>异步导出</strong></td><td><code>ExportTaskAppService</code> 提交时入队</td><td><code>ExportTaskHostedService</code></td><td><code>Sys_Export_Task</code></td></tr></tbody></table><p>两者都继承框架的 <code>XiHanBackgroundServiceBase&lt;T&gt;</code>（封装了循环拉取、并发控制、重试、优雅停机、运行统计），子类实现 <code>FetchWorkItemsAsync</code>（取任务）和 <code>ProcessItemAsync</code>（处理任务）两个抽象方法，并重写 <code>ExecuteAsync</code> 在循环前做一次启动复位。</p><h3 id="崩溃恢复" tabindex="-1">崩溃恢复 <a class="header-anchor" href="#崩溃恢复" aria-label="Permalink to &quot;崩溃恢复&quot;">​</a></h3><p>进程被杀时可能留下一批处于在途状态（发件箱 <code>Sending</code>、导出 <code>Processing</code>）的行——它们既不会被再次领取，也永远不会完成。所以后台服务<strong>启动时先做一次复位</strong>：发件箱用 <code>ResetInFlightAndCollectPendingAsync</code> 把残留的 <code>Sending</code> 改回 <code>Pending</code> 并收集待发送重新投递；导出用 <code>ResetOrphanedProcessingAsync</code> 复位后再由 <code>GetPendingIdsAsync</code> 取出待执行任务重投。</p><p>新增异步链路时这一步别漏，否则一次异常重启就会永久卡住一批任务。</p><h3 id="与框架后台作业的分工" tabindex="-1">与框架后台作业的分工 <a class="header-anchor" href="#与框架后台作业的分工" aria-label="Permalink to &quot;与框架后台作业的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th>需求</th><th>用什么</th></tr></thead><tbody><tr><td>周期性/定时触发（每天凌晨跑报表）</td><td>框架 <a href="https://framework.docs.xihanfun.com/packages/tasks" target="_blank" rel="noreferrer">Tasks</a> 的调度器 + <code>Sys_Task</code> 配置</td></tr><tr><td>一次性 fire-and-forget，入队即返回</td><td>框架 <code>IBackgroundJobManager.EnqueueAsync</code></td></tr><tr><td><strong>持续拉队列消费，且要业务表做状态机</strong></td><td><strong><code>XiHanBackgroundServiceBase&lt;T&gt;</code> + <code>IRedisDelayQueue&lt;T&gt;</code>（BasicApp 的两条链路都是这种）</strong></td></tr><tr><td>等人审批的长流程</td><td><a href="./workflow">工作流</a></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>BasicApp 的写路径大量使用本地事件解耦（如授权变更 → 写权限变更日志、待办创建 → 发站内通知）。</p><div class="warning custom-block"><p class="custom-block-title">事件处理器必须显式登记</p><p>本地事件总线只订阅登记在 <code>XiHanLocalEventBusOptions.Handlers</code> 里的处理器类型。裸 <code>services.AddTransient&lt;MyHandler&gt;()</code> <strong>不会被订阅，静默失败</strong>。必须用 <code>AddSaasLocalEventHandler&lt;T&gt;()</code>（内部 <code>AddTransient</code> + 把类型加进 <code>XiHanLocalEventBusOptions.Handlers</code>），并在 <code>AddSaasEventHandlers</code> 里登记。</p></div><p>发布时机（框架保证）：</p><ul><li><strong>本地事件在事务提交前</strong>发布——处理器可能继续写库，这些写入必须落在同一事务里。</li><li><strong>分布式事件在事务提交成功后</strong>发布——避免「事务回滚了事件照发」的幽灵事件。</li></ul><h2 id="排查速查" tabindex="-1">排查速查 <a class="header-anchor" href="#排查速查" aria-label="Permalink to &quot;排查速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>改了配置/菜单/字典，页面还是旧值</td><td>写侧漏调对应的 <code>InvalidateXxxAsync</code></td></tr><tr><td>偶发读到旧值且不自愈</td><td>失效没走 <code>considerUow: true</code>，在提交前清了缓存</td></tr><tr><td>授权改了不生效</td><td><code>InvalidateAuthorizationAsync</code> 没调；注意传 <code>userId</code> 只清单个用户</td></tr><tr><td>邮件/短信卡在 <code>Sending</code> 不动</td><td>进程崩溃残留，检查后台服务的启动复位逻辑是否执行</td></tr><tr><td>导出任务提交后没反应</td><td>队列是否入队（是否在提交后）、后台服务是否在跑</td></tr><tr><td>事件处理器不触发</td><td>没加进 <code>XiHanLocalEventBusOptions.Handlers</code></td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./request-lifecycle">请求生命周期</a>：收尾顺序的完整时序</li><li><a href="./data-model">数据模型</a>：事实源表的结构</li><li><a href="./messaging">消息中心</a>：邮件/短信/通知的业务设计</li><li><a href="https://framework.docs.xihanfun.com/packages/caching" target="_blank" rel="noreferrer">Caching 包</a> / <a href="https://framework.docs.xihanfun.com/packages/tasks" target="_blank" rel="noreferrer">Tasks 包</a>：框架侧实现</li></ul>`,41)])])}const u=t(o,[["render",c]]);export{g as __pageData,u as default};
